  /** 大駒が滑って行けるマスの数(相手の駒を取れるマスを含む、最大16) */
  function mobility(s, pc) {
    const sl = SLIDES[pc];
    const oLo = pc & WHITE ? 0 : 16;
    let n = 0;
    for (let k = 0; k < sl.length; k++) {
      const o = sl[k];
      let t = s + o;
      while (board[t] === 0) { n++; t += o; }
      const tp = board[t];
      if (tp > oLo && tp < oLo + 16) n++;
    }
    return n > 16 ? 16 : n;
  }

  /** 玉の周り8マス: 相手が利かせている数(KS_A)と、そのうち自分の駒が守っていない数(KS_U) */
  let KS_A = 0, KS_U = 0, KS_E = 0, KS_H = 0;
  function kingSafety(c) {
    const k = kingSq[c];
    let a = 0, u = 0, esc = 0;
    const ownLo = c ? 16 : 0;
    // 玉自身の利きは数えないため、いったん盤から外す
    const kp = board[k];
    board[k] = 0;
    for (let i = 0; i < 8; i++) {
      const s = k + DIRS8[i];
      const tp = board[s];
      if (tp === WALL) continue;
      if (isAttacked(s, c ^ 1)) {
        a++;
        if (!isAttacked(s, c)) u++;
      } else if (!(tp > ownLo && tp < ownLo + 16)) {
        esc++; // 空きマスか相手の駒で、相手が利かせていない = 逃げ道
      }
    }
    board[k] = kp;
    const h = (c ^ 1) * 8;
    const hp = hands[h + G] + hands[h + S] + hands[h + R] + hands[h + B];
    KS_A = a; KS_U = u; KS_E = esc; KS_H = hp > 3 ? 3 : hp;
  }

  function evaluate() {
    let sc = mat;
    const kb = kingSq[0], kw = kingSq[1];
    const rb = ROW[kb], cb = COL[kb], rw = ROW[kw], cw = COL[kw];
    for (let i = 0; i < 81; i++) {
      const s = SQ81[i], pc = board[s];
      if (pc === 0) continue;
      const r = ROW[s], c = COL[s];
      const e = c > 4 ? 8 - c : c;
      if (pc < 16) {
        if (pc === K) continue;
        const base = pc * REL;
        const dxw = c > cw ? c - cw : cw - c, dxb = c > cb ? c - cb : cb - c;
        sc += EV[OFF_A + base + (r - rw + 8) * 9 + dxw] + EV[OFF_D + base + (r - rb + 8) * 9 + dxb] + EV[OFF_PS + pc * 45 + r * 5 + e];
        if (MOB_SLOT[pc] >= 0) sc += EV[OFF_MOB + MOB_SLOT[pc] * 17 + mobility(s, pc)];
      } else {
        const t = pc & 15;
        if (t === K) continue;
        const base = t * REL;
        const dxb = c > cb ? c - cb : cb - c, dxw = c > cw ? c - cw : cw - c;
        sc -= EV[OFF_A + base + (rb - r + 8) * 9 + dxb] + EV[OFF_D + base + (rw - r + 8) * 9 + dxw] + EV[OFF_PS + t * 45 + (8 - r) * 5 + e];
        if (MOB_SLOT[t] >= 0) sc -= EV[OFF_MOB + MOB_SLOT[t] * 17 + mobility(s, pc)];
      }
    }
    kingSafety(0);
    sc += EV[OFF_KA + KS_A] + EV[OFF_KU + KS_U] + EV[OFF_KH + KS_U * 4 + KS_H] + EV[OFF_KE + KS_E];
    kingSafety(1);
    sc -= EV[OFF_KA + KS_A] + EV[OFF_KU + KS_U] + EV[OFF_KH + KS_U * 4 + KS_H] + EV[OFF_KE + KS_E];
    sc += EV[OFF_K + rb * 5 + edge(cb)] - EV[OFF_K + (8 - rw) * 5 + edge(cw)];
    for (let t = 1; t <= 7; t++) {
      sc += hands[t] * EV[OFF_HK + t * 9 + rw] - hands[8 + t] * EV[OFF_HK + t * 9 + (8 - rb)];
    }
    return side ? -sc : sc;
  }

  /** 学習用: evaluate() と同じ値を (パラメータ番号, 係数) の組で書き出す(先手から見た値) */
  function extractFeatures(idx, coef) {
    let n = 0;
    const add = (i, c) => { idx[n] = i; coef[n] = c; n++; };
    const kb = kingSq[0], kw = kingSq[1];
    const rb = ROW[kb], cb = COL[kb], rw = ROW[kw], cw = COL[kw];
    for (let i = 0; i < 81; i++) {
      const s = SQ81[i], pc = board[s];
      if (pc === 0) continue;
      const r = ROW[s], c = COL[s], e = edge(c);
      const t = pc & 15;
      if (t === K) continue;
      if (pc < 16) {
        add(OFF_MB + t, 1);
        add(OFF_A + t * REL + (r - rw + 8) * 9 + Math.abs(c - cw), 1);
        add(OFF_D + t * REL + (r - rb + 8) * 9 + Math.abs(c - cb), 1);
        add(OFF_PS + t * 45 + r * 5 + e, 1);
        if (MOB_SLOT[t] >= 0) add(OFF_MOB + MOB_SLOT[t] * 17 + mobility(s, pc), 1);
      } else {
        add(OFF_MB + t, -1);
        add(OFF_A + t * REL + (rb - r + 8) * 9 + Math.abs(c - cb), -1);
        add(OFF_D + t * REL + (rw - r + 8) * 9 + Math.abs(c - cw), -1);
        add(OFF_PS + t * 45 + (8 - r) * 5 + e, -1);
        if (MOB_SLOT[t] >= 0) add(OFF_MOB + MOB_SLOT[t] * 17 + mobility(s, pc), -1);
      }
    }
    kingSafety(0);
    add(OFF_KA + KS_A, 1); add(OFF_KU + KS_U, 1); add(OFF_KH + KS_U * 4 + KS_H, 1); add(OFF_KE + KS_E, 1);
    kingSafety(1);
    add(OFF_KA + KS_A, -1); add(OFF_KU + KS_U, -1); add(OFF_KH + KS_U * 4 + KS_H, -1); add(OFF_KE + KS_E, -1);
    add(OFF_K + rb * 5 + edge(cb), 1);
    add(OFF_K + (8 - rw) * 5 + edge(cw), -1);
    for (let t = 1; t <= 7; t++) {
      if (hands[t]) { add(OFF_MH + t, hands[t]); add(OFF_HK + t * 9 + rw, hands[t]); }
      if (hands[8 + t]) { add(OFF_MH + t, -hands[8 + t]); add(OFF_HK + t * 9 + (8 - rb), -hands[8 + t]); }
    }
    return n;
  }

